mapper.select:
select u.user_id, u.nick_name as user_name, u.dept_id, d.dept_name, coalesce(sum(a.objective_score), 0) as objective_score, coalesce(sum(a.subjective_score), 0) as subjective_score, coalesce(sum(a.objective_score), 0) + coalesce(sum(a.subjective_score), 0) as total_score, max(a.score_status) as score_status from answer_record a join sys_user u on a.user_id = u.user_id left join sys_dept d on u.dept_id = d.dept_id
and a.competition_id = #{competitionId} and a.batch_id = #{batchId}
group by u.user_id, u.nick_name, u.dept_id, d.dept_name order by total_score desc, u.nick_name
